!function(){const e=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1,rootMargin:"0px 0px -40px 0px"});document.querySelectorAll(".reveal").forEach(t=>e.observe(t)),document.querySelectorAll('a[href^="#"]').forEach(e=>{e.addEventListener("click",t=>{const r=document.querySelector(e.getAttribute("href"));r&&(t.preventDefault(),r.scrollIntoView({behavior:"smooth",block:"start"}))})}),document.querySelectorAll(".faq-q").forEach(e=>{e.addEventListener("click",()=>{e.closest(".faq-item").classList.toggle("open")})})}();